def execute(arguments):
    """
    创建计划任务

    参数:
        arguments (dict): 包含以下字段
            - task_name (str): 任务名称，必填
            - task_type (str): 任务类型，"delay"（延迟执行）或 "scheduled"（定时执行）
            - delay_seconds (int): 延迟秒数，task_type 为 "delay" 时必填
            - scheduled_time (str): 计划执行时间，ISO格式，task_type 为 "scheduled" 时必填
            - action (str): 要执行的动作/命令，必填
            - action_params (dict): 动作参数，可选

    返回:
        dict: 包含任务信息的字典
            - success (bool): 是否成功
            - task_name (str): 任务名称
            - task_type (str): 任务类型
            - execute_at (str): 计划执行时间（ISO格式）
            - action (str): 执行动作
            - action_params (dict): 动作参数
            - message (str): 提示信息
            - error (str): 错误信息（失败时）
    """
    import json
    from datetime import datetime, timedelta

    task_name = arguments.get("task_name", "")
    task_type = arguments.get("task_type", "delay")
    delay_seconds = arguments.get("delay_seconds", 0)
    scheduled_time = arguments.get("scheduled_time", "")
    action = arguments.get("action", "")
    action_params = arguments.get("action_params", {})

    if not task_name:
        return {"success": False, "error": "请提供任务名称"}

    if not action:
        return {"success": False, "error": "请提供任务动作"}

    try:
        if task_type == "delay":
            if delay_seconds <= 0:
                return {"success": False, "error": "延迟时间必须大于0"}

            execute_at = datetime.now() + timedelta(seconds=delay_seconds)

            return {
                "success": True,
                "task_name": task_name,
                "task_type": task_type,
                "execute_at": execute_at.isoformat(),
                "action": action,
                "action_params": action_params,
                "message": f"任务将在 {delay_seconds} 秒后执行"
            }

        elif task_type == "scheduled":
            if not scheduled_time:
                return {"success": False, "error": "请提供计划执行时间"}

            try:
                execute_at = datetime.fromisoformat(scheduled_time)
            except ValueError:
                return {"success": False, "error": "时间格式无效，请使用ISO格式 (YYYY-MM-DD HH:MM:SS)"}

            if execute_at < datetime.now():
                return {"success": False, "error": "计划时间不能早于当前时间"}

            return {
                "success": True,
                "task_name": task_name,
                "task_type": task_type,
                "execute_at": execute_at.isoformat(),
                "action": action,
                "action_params": action_params,
                "message": f"任务已计划在 {scheduled_time} 执行"
            }

        else:
            return {"success": False, "error": f"未知的任务类型: {task_type}"}
    except Exception as e:
        return {"success": False, "error": f"创建任务失败: {str(e)}"}
